"""k6_ssd — generated by torch-helion (do not edit).

Mamba-2 scan (quadratic form): batch=2 seq=256 heads=32 head_dim=32 state_dim=32
  acc = exp(c_i) * sum_j (C_i.B_j) causal_ij exp(-c_j) dt_j x_j  +  D * x_i
  mul_10 = mul(acc, in0) 
  store mul_10 <- mul_10
Planned tiles: {'tile_m': 256, 'tile_n': 256}  (analytic estimate 66,883 cycles)

Run through Loom from the repository root:

    uv run python results/mamba/kernels/k6_ssd.py --config results/mamba/kernels/config_files/k6_ssd.json --njobs 8 --debug --topk-candidates 1
"""

from __future__ import annotations

import sys

import torch
import helion
import helion.language as hl

from loom import LoomKernel
from loom.loom_utils.kernel_size import resolve_kernel_shape_args
from helion_mlir.custom_op import broadcast  # noqa: F401  (registers the op)


_SSD_B, _SSD_S, _SSD_H, _SSD_N, _SSD_PAD = 2, 256, 32, 32, 32
_SSD_T, _SSD_HP = 512, 1024

def _k6_ssd(c: torch.Tensor, b: torch.Tensor, x: torch.Tensor, cum: torch.Tensor, dt: torch.Tensor, mask: torch.Tensor, dskip: torch.Tensor, xskip: torch.Tensor, in0: torch.Tensor, p: hl.constexpr) -> tuple[torch.Tensor, ...]:
    c_v = c.reshape(_SSD_B, _SSD_S, _SSD_H, _SSD_N).permute(0, 2, 1, 3)
    b_v = b.reshape(_SSD_B, _SSD_S, _SSD_H, _SSD_N).permute(0, 2, 3, 1)
    x_v = x.reshape(_SSD_B, _SSD_S, _SSD_H, p).permute(0, 2, 1, 3)
    cum_v = cum.reshape(_SSD_B, _SSD_S, _SSD_H, _SSD_PAD).permute(0, 2, 1, 3)
    dt_v = dt.reshape(_SSD_B, _SSD_S, _SSD_H, _SSD_PAD).permute(0, 2, 1, 3)
    dskip_v = dskip.reshape(_SSD_B, _SSD_S, _SSD_H, p).permute(0, 2, 1, 3)
    xskip_v = xskip.reshape(_SSD_B, _SSD_S, _SSD_H, p).permute(0, 2, 1, 3)
    in0_v = in0.reshape(_SSD_B, _SSD_S, _SSD_H, p).permute(0, 2, 1, 3)
    out_mul_10 = torch.empty([_SSD_T, _SSD_HP], dtype=torch.float16, device=c.device)
    o4_mul_10 = out_mul_10.reshape(_SSD_B, _SSD_S, _SSD_H, p).permute(0, 2, 1, 3)
    for tile_b, tile_h, tile_m in hl.tile([_SSD_B, _SSD_H, _SSD_S], block_size=[1, 1, None]):
        acc0 = hl.zeros([tile_m, p], dtype=torch.float16)
        ci = torch.amax(cum_v[tile_b.begin, tile_h.begin, tile_m, :], -1, keepdim=True)
        q = c_v[tile_b.begin, tile_h.begin, tile_m, :]
        xm = xskip_v[tile_b.begin, tile_h.begin, tile_m, :]
        dm = dskip_v[tile_b.begin, tile_h.begin, tile_m, :]
        ld_2 = in0_v[tile_b.begin, tile_h.begin, tile_m, :]
        for tile_n in hl.tile(_SSD_S):
            kt = b_v[tile_b.begin, tile_h.begin, :, tile_n]
            w = torch.matmul(q, kt) * mask[tile_m, tile_n]
            cj = torch.amax(cum_v[tile_b.begin, tile_h.begin, tile_n, :], -1, keepdim=True)
            dj = torch.amax(dt_v[tile_b.begin, tile_h.begin, tile_n, :], -1, keepdim=True)
            scale = torch.exp(cj * -1.0) * dj
            v = x_v[tile_b.begin, tile_h.begin, tile_n, :] * broadcast(scale, 1, [scale.size(0), p])
            acc0 = torch.addmm(acc0, w, v)
        acc0 = acc0 * broadcast(torch.exp(ci), 1, [ci.size(0), p])
        acc = acc0 + xm * dm
        mul_10_1 = acc * ld_2
        o4_mul_10[tile_b.begin, tile_h.begin, tile_m, :] = mul_10_1
    return out_mul_10,


class K6Ssd(LoomKernel):
    """Loom entry point for kernel ``k6_ssd``."""

    kernel_name = "k6_ssd"
    assume_divisible: bool = True

    ARG_SHAPES = [('c', [512, 1024]), ('b', [512, 1024]), ('x', [512, 1024]), ('cum', [512, 1024]), ('dt', [512, 1024]), ('mask', [256, 256]), ('dskip', [512, 1024]), ('xskip', [512, 1024]), ('in0', [512, 1024])]
    CONSTEXPRS = [('p', 32)]
    TILES = {'tile_m': 256, 'tile_n': 256}

    kernel = helion.kernel(
        static_shapes=False,
        autotune_config_overrides={
            "range_unroll_factors": [0, 0, 0, 0],
            "range_num_stages": [0, 0, 0, 0],
        },
    )(_k6_ssd)

    def __init__(self, shape: dict[str, int] | None = None) -> None:
        if shape:
            raise SystemExit("generated kernels have fixed shapes; regenerate with torch-helion instead")

    @classmethod
    def bind_args(cls) -> tuple:
        args = [torch.empty(shape, dtype=torch.float16) for _, shape in cls.ARG_SHAPES]
        return tuple(args + [v for _, v in cls.CONSTEXPRS])


if __name__ == "__main__":
    try:
        shape, normalized_argv = resolve_kernel_shape_args(sys.argv)
    except ValueError as exc:
        raise SystemExit(str(exc)) from exc

    sys.argv = normalized_argv
    K6Ssd(shape).run()
